namespace ghidra.framework.main.logviewer.ui;




using org.apache.logging.log4j;

using docking.widgets.table;
using docking.widgets.table;
using generic.theme;

/**
 * Renderer for the {@link FVTable} that will set the background color based on
 * the text contents. This is intended to be used only for the log level 
 * column.
 */
public class LogLevelTableCellRenderer : GTableCellRenderer {

	private static readonly Color TRACE_COLOR = new GColor("color.bg.logviwer.table.trace");
	private static readonly Color DEBUG_COLOR = new GColor("color.bg.logviwer.table.debug");
	private static readonly Color INFO_COLOR = new GColor("color.bg.logviwer.table.info");
	private static readonly Color WARN_COLOR = new GColor("color.bg.logviwer.table.warn");
	private static readonly Color ERROR_COLOR = new GColor("color.bg.logviwer.table.error");
	private static readonly Color FATAL_COLOR = new GColor("color.bg.logviwer.table.fatal");
	private static readonly Color FG = new GColor("color.fg.logviewer.table");
	private static readonly Color FG_SELECTED = new GColor("color.fg.logviewer.table.selected");

	/* @Override */
	public Component getTableCellRendererComponent(GTableCellRenderingData data) {

		base.getTableCellRendererComponent(data);

		object value = data.getValue();

		setForeground(data.isSelected() ? FG_SELECTED : FG);

		if (value.toString().equalsIgnoreCase(Level.DEBUG.toString())) {
			setBackground(DEBUG_COLOR);
		}
		else if (value.toString().equalsIgnoreCase(Level.TRACE.toString())) {
			setBackground(TRACE_COLOR);
		}
		else if (value.toString().equalsIgnoreCase(Level.WARN.toString())) {
			setBackground(WARN_COLOR);
		}
		else if (value.toString().equalsIgnoreCase(Level.INFO.toString())) {
			setBackground(INFO_COLOR);
		}
		else if (value.toString().equalsIgnoreCase(Level.ERROR.toString())) {
			setBackground(ERROR_COLOR);
		}
		else if (value.toString().equalsIgnoreCase(Level.FATAL.toString())) {
			setBackground(FATAL_COLOR);
		}

		return this;
	}

}
